import json,glob,os,pickle,datetime,re
B='/root/.claude/projects/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/subagents/workflows'
RUNS={'wf_603242ca-111':8,'wf_f747fd3e-9e4':9}
def ts(s): return datetime.datetime.fromisoformat(s.replace('Z','+00:00')).timestamp()
def rbytes(c):
    if isinstance(c,str): return len(c)
    if isinstance(c,list):
        n=0
        for b in c:
            if isinstance(b,dict):
                if b.get('type')=='text': n+=len(b.get('text',''))
                else: n+=len(json.dumps(b))
            else: n+=len(str(b))
        return n
    return len(json.dumps(c))
def rtext(c):
    if isinstance(c,str): return c
    if isinstance(c,list): return '\n'.join(b.get('text','') for b in c if isinstance(b,dict) and b.get('type')=='text')
    return ''
def parse_agent(path):
    turns=[]; byid={}
    results={}   # tool_use_id -> dict
    pending_att=0  # reminder chars since last assistant
    first_user=[]  # first user msgs (str)
    att_sizes=[]   # attachments before first assistant: (type,chars)
    other_user=[] # (turn_index_before, chars) for user text msgs mid-conversation
    sys_len=0
    for l in open(path):
        d=json.loads(l); t=d['type']
        if t=='attachment':
            a=d['attachment']; sz=len(json.dumps(a))
            if a.get('type')=='prompt_snapshot':
                if not turns:
                    sp=a.get('systemPrompt'); sys_len=len(json.dumps(sp))
                    tl=a.get('tools'); 
                    if tl is not None: sys_len+=len(json.dumps(tl))
                continue
            if not turns: att_sizes.append((a.get('type'),sz))
            else: pending_att+=len(d.get('rendered') or '') if d.get('rendered') else sz//2
            continue
        if t=='user':
            c=d['message']['content']
            if isinstance(c,str):
                if not turns: first_user.append(len(c))
                else: other_user.append((len(turns),len(c)))
            else:
                for b in c:
                    if b.get('type')=='tool_result':
                        results[b['tool_use_id']]=dict(bytes=rbytes(b.get('content')),err=bool(b.get('is_error')),ts=ts(d['timestamp']),text=rtext(b.get('content')))
                    elif b.get('type')=='text':
                        if not turns: first_user.append(len(b['text']))
                        else: other_user.append((len(turns),len(b['text'])))
            continue
        if t=='assistant':
            m=d['message']; mid=m['id']
            if mid not in byid:
                tr=dict(id=mid,ts0=ts(d['timestamp']),ts1=ts(d['timestamp']),calls=[],textchars=0,thinking=False,att_before=pending_att,usage=None,stop=None,out=0)
                pending_att=0
                byid[mid]=tr; turns.append(tr)
            tr=byid[mid]; tr['ts1']=ts(d['timestamp'])
            u=m['usage']; tr['usage']=u; tr['out']=max(tr['out'],u.get('output_tokens',0))
            if m.get('stop_reason'): tr['stop']=m['stop_reason']
            for b in m['content']:
                if b['type']=='tool_use': tr['calls'].append(dict(id=b['id'],name=b['name'],input=b['input']))
                elif b['type']=='text': tr['textchars']+=len(b['text'])
                elif b['type']=='thinking': tr['thinking']=True
    for tr in turns:
        for c in tr['calls']:
            r=results.get(c['id'])
            c['rbytes']=r['bytes'] if r else 0
            c['rts']=r['ts'] if r else None
            c['err']=r['err'] if r else False
            c['text']=r['text'] if r else ''
    return dict(turns=turns,first_user=first_user,att_sizes=att_sizes,other_user=other_user,sys_len=sys_len)
if __name__=='__main__':
    out={}
    for run,b in RUNS.items():
        lab={}
        for l in open(f'{B}/{run}/journal.jsonl'):
            d=json.loads(l)
            if d['type']=='started': lab[d['agentId']]=d.get('label')
        for aid,label in lab.items():
            p=f'{B}/{run}/agent-{aid}.jsonl'
            a=parse_agent(p); a['batch']=b; a['label']=label; a['aid']=aid; a['run']=run
            out[aid]=a
    pickle.dump(out,open('agents.pkl','wb'))
    for aid,a in out.items():
        tt=a['turns']; w=sum(t['usage']['cache_creation_input_tokens']+t['usage']['input_tokens'] for t in tt)
        print(a['batch'],a['label'],aid,len(tt),'writes',w,'sys',a['sys_len'],'first_user',a['first_user'],'att',sum(x[1] for x in a['att_sizes']))
======
import pickle,json,os,re,collections
from cls2 import classify
A=pickle.load(open('agents.pkl','rb'))
TPC=0.40  # tokens per char of result/call text
PER_RES=110
def role_of(label):
    base=label.split(':')[0]
    return {'rung':'rung','skeptic':'skeptic','skeptic2':'skeptic2','judge':'judge','repair':'repair','gather':'gather','gate':'gate','review':'review','commit':'commit'}[base] if label not in('judge:review','repair:review','gate:after-review') else {'judge:review':'judge:review','repair:review':'repair:review','gate:after-review':'gate'}[label]
OUT={}
for aid,a in A.items():
    T=a['turns']; role=role_of(a['label'])
    calls=[]; turns=[]
    u=T[0]['usage']
    ctx1=u['cache_creation_input_tokens']+u['cache_read_input_tokens']+u['input_tokens']
    w1=u['cache_creation_input_tokens']+u['input_tokens']
    brief_chars=a['first_user'][-1]
    tot_think=0;tot_res=0;tot_inp=0;tot_refill=0;tot_new=0
    prev_ctx=ctx1
    for k in range(1,len(T)):
        uk=T[k]['usage']
        ctx=uk['cache_creation_input_tokens']+uk['cache_read_input_tokens']+uk['input_tokens']
        wk=uk['cache_creation_input_tokens']+uk['input_tokens']
        new=ctx-prev_ctx
        refill=max(0,wk-new)
        pc=T[k-1]['calls']
        items=[]
        for c in pc:
            r=classify(c['name'],c['input'])
            res=(TPC*len(c.get('text','')) + PER_RES) if c['rbytes'] or c.get('rts') else 0
            res=TPC*c['rbytes']+PER_RES if c.get('rts') else 0
            inp=TPC*len(json.dumps(c['input']))
            items.append((c,r,res,inp))
        sres=sum(i[2] for i in items); sinp=sum(i[3] for i in items)
        if sres+sinp>new and sres+sinp>0:
            f=new/(sres+sinp); items=[(c,r,res*f,inp*f) for c,r,res,inp in items]; sres*=f; sinp*=f
        think=new-sres-sinp
        gap=T[k]['ts0']-max([c['rts'] for c in pc if c.get('rts')] or [T[k-1]['ts1']])
        for c,r,res,inp in items:
            calls.append(dict(aid=aid,turn=k-1,name=c['name'],cls=r['cls'],sub=r.get('sub'),files=r.get('files',[]),kinds=r.get('kinds',[]),res=res,inp=inp,rbytes=c['rbytes'],id=c['id'],input=c['input']))
        turns.append(dict(k=k,new=new,writes=wk,refill=refill,think=think,gap=gap,res=sres,inp=sinp,prev_calls=len(pc),prev_cls=[classify(c['name'],c['input'])['cls'] for c in pc],ts=T[k]['ts0']))
        tot_think+=think;tot_res+=sres;tot_inp+=sinp;tot_refill+=refill;tot_new+=new
        prev_ctx=ctx
    W=w1+sum(t['writes'] for t in turns)
    OUT[aid]=dict(aid=aid,batch=a['batch'],label=a['label'],role=role,calls=calls,turns=turns,ctx1=ctx1,w1=w1,cr1=u['cache_read_input_tokens'],brief_chars=brief_chars,W=W,think=tot_think,res=tot_res,inp=tot_inp,refill=tot_refill,new=tot_new,nturns=len(T),
        t0=T[0]['ts0'],t1=T[-1]['ts1'])
    # check closure
    OUT[aid]["resid"]=W-(w1+tot_new+tot_refill)
pickle.dump(OUT,open('acct.pkl','wb'))
for aid,o in OUT.items():
    print(o['batch'],o['label'],o['W'],'first',o['w1'],'refill',round(o['refill']),'think',round(o['think']),'res',round(o['res']),'inp',round(o['inp']))
